    array.push(binVol, 0.0)
    i := i + 1
}

k = 0
while k < profLen {
    typ = (high[k] + low[k] + close[k]) / 3
    vk = volume[k]
    bk = floor((typ - ll) / rng * rows)
    if bk < 0 { bk := 0 }
    if bk > rows - 1 { bk := rows - 1 }
    array.set(binVol, bk, array.get(binVol, bk) + vk)
    k := k + 1
}

// ─── Point of control: bin with max volume ──────────────────────────
pocBin = 0
pocVal = array.get(binVol, 0)
i = 1
while i < rows {
    v = array.get(binVol, i)
    if v > pocVal {
        pocVal := v
        pocBin := i
    }
    i := i + 1
}
totalVol = array.sum(binVol)
pocShare = 0.0
if totalVol > 0 { pocShare := pocVal / totalVol }
pocPrice = ll + (pocBin + 0.5) / rows * rng

// ─── Value area: symmetric expansion from POC by adjacent volume ───
vaLowBin = pocBin
vaHighBin = pocBin
accum = pocVal
target = totalVol * vaPct / 100
guard = 0
