    leftVal = 0 - 1.0
    if vaLowBin > 0 { leftVal := array.get(binVol, vaLowBin - 1) }
    rightVal = 0 - 1.0
    if vaHighBin < rows - 1 { rightVal := array.get(binVol, vaHighBin + 1) }
    if rightVal >= leftVal and vaHighBin < rows - 1 {
        vaHighBin := vaHighBin + 1
        accum := accum + rightVal
    } else {
        if vaLowBin > 0 {
            vaLowBin := vaLowBin - 1
            accum := accum + leftVal
        }
    }
    guard := guard + 1
}
vaHighPrice = ll + (vaHighBin + 1) / rows * rng
vaLowPrice = ll + vaLowBin / rows * rng
